func TestTokenizeSearchSplitsCompounds(t *testing.T) {
	analyzer, err := tokenizer.New(ipa.Dict(), tokenizer.OmitBosEos())
	if err != nil {
		t.Fatal(err)
	}
	tokens := tokenize(analyzer, "東京都庁に行きます")
	found := false
	for _, token := range tokens {
		if token == "東京" {
			found = true
			break
		}
	}
	if !found {
		t.Fatalf("expected 東京 in %v", tokens)
	}
}

func TestQueryGroupsKeepVerbVariantsTogetherWithoutAuxiliaries(t *testing.T) {
	analyzer, err := tokenizer.New(ipa.Dict(), tokenizer.OmitBosEos())
	if err != nil {
		t.Fatal(err)
	}
	groups := queryGroups(analyzer, "東京 行きました")
	if len(groups) != 2 || len(groups[1]) != 2 || groups[1][0] != "行き" || groups[1][1] != "行く" {
		t.Fatalf("unexpected query groups: %v", groups)
	}
}

package store

import (
